  app: ["info"],
  nodes: ["catalog"],
  templates: ["list"],
  workflows: ["list", "get", "save", "remove"],
  files: ["import"],
  runs: ["start", "get", "list", "nodeOutput", "resume", "cancel"],
  requirements: ["list", "get", "edit", "decide"],
  audit: ["list"],
  settings: ["get", "save", "secrets", "setSecret"],
