  return `reqflow:${namespace}.${method}`;
}

export const IPC_INVOKE_CHANNELS: ReadonlySet<string> = new Set(
  Object.entries(IPC_INVOKE_METHODS).flatMap(([ns, methods]) =>
    methods.map((m) => ipcChannel(ns, m)),
  ),
