1	import type { z } from "zod";
2	import type { AuditEvent, AuditEventInput } from "./audit";
3	
4	/**
5	 * Service interfaces handed to nodes via NodeContext. Implementations live elsewhere
6	 * (llm → @reqflow/llm, audit/files → @reqflow/db, web search → nodes/research) and are
7	 * wired together in the Electron main process (apps/desktop/src/main). Nodes never read env vars or the DB directly.
8	 */
9	
10	export type ModelTier = "default" | "fast";
11	
12	export interface LlmObjectRequest<T> {
13	  system?: string;
14	  prompt: string;
15	  schema: z.ZodType<T>;

34	
35	export interface NodeDefinition<C extends z.ZodType = z.ZodType> {
36	  type: string; // unique, stable registry key: "<category>.<name>", e.g. "analysis.extract_signals"
37	  label: string; // palette / canvas title
38	  description: string; // one or two sentences for the palette tooltip
39	  category: NodeCategory;
40	  consumes: DataKey[]; // editor warns if no upstream node produces these
41	  produces: DataKey[];
42	  configSchema: C; // drives the config form (served as JSON Schema by api.nodes.catalog())
43	  /** Must be deterministic given (input, config, LLM output) and must throw on bad input — no silent skips. */
44	  run(input: PipelineData, config: z.infer<C>, ctx: NodeContext): Promise<NodeResult>;
45	}
