28	/** Pure (Electron-free) so it can be unit-tested: route one IPC call to its handler. */
29	export async function dispatch(
30	  handlers: ReqflowHandlers,
31	  namespace: string,
32	  method: string,
33	  args: unknown[],
34	): Promise<IpcResult<unknown>> {
35	  const ns = (handlers as unknown as Record<string, Record<string, unknown> | undefined>)[
36	    namespace
37	  ];
38	  const fn = ns?.[method];
39	  if (typeof fn !== "function") {
40	    return {
41	      ok: false,
42	      error: { code: "unknown_method", message: `No handler for ${namespace}.${method}` },
43	    };
44	  }
45	  try {

31	  // The window never navigates away from the app; http(s) links open in the user's browser.
32	  win.webContents.setWindowOpenHandler(({ url }) => {
33	    if (/^https?:\/\//.test(url)) void shell.openExternal(url);
34	    return { action: "deny" };
35	  });
36	  win.webContents.on("will-navigate", (event, url) => {
37	    const current = new URL(win.webContents.getURL());
38	    const next = new URL(url);
39	    if (next.origin !== current.origin || next.pathname !== current.pathname)
40	      event.preventDefault();
41	  });
42	
43	  const devUrl = process.env.ELECTRON_RENDERER_URL;
44	  if (!app.isPackaged && devUrl) void win.loadURL(devUrl);
45	  else void win.loadFile(join(__dirname, "../renderer/index.html"));
46	  return win;
47	}
